{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Replace pairwise BPR with pointwise logistic loss to constrain positive and negative scores separately. Preserve valid-position masking, sampling, architecture, inference, and all training settings; retain one checkpoint per dataset.",
      "edits": [
        {
          "find": "    loss = -torch.log(torch.sigmoid(pos_scores - neg_scores) + 1e-8)",
          "replace": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)"
        }
      ]
    }
  ],
  "change_summary": "Average pointwise positive and negative logistic losses over valid target positions for all four datasets. Checkpoint shapes and predictor remain compatible."
}
